// src/components/Admin/AdminDashboard.js
import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import Analytics from './Analytics';
import Tables from './Tables';
import Kitchen from './Kitchen';
import AddProduct from './AddProduct';
import './AdminDashboard.css';

export default function AdminDashboard({
  orders = [],
  tables = [],
  menuItems = [],
  chefs = [], // Accept chefs prop
  updateOrderStatus,
  deleteTable,
  addTable,
  addProduct,
}) {
  const [active, setActive] = useState('analytics');
  const [filter, setFilter] = useState('');
  const [appliedFilter, setAppliedFilter] = useState('');
  const [sidebarOpen, setSidebarOpen] = useState(false);
  
  const navigate = useNavigate(); // Hook for navigation

  // helper to close sidebar on mobile after navigation
  const setActiveAndClose = (section) => {
    setActive(section);
    if (window.innerWidth <= 900) setSidebarOpen(false);
  };

  // Logic for search filter (blurs the rest of the container)
  const filterBlur = appliedFilter ? 'blur(4px)' : 'none';
  const checkFilter = (text) => {
    if (!appliedFilter) return true;
    return String(text).toLowerCase().includes(appliedFilter.toLowerCase());
  }

  return (
    <div className={`admin-dashboard ${sidebarOpen ? 'sidebar-open' : ''}`}>
      {/* SIDEBAR */}
      <aside className={`sidebar ${sidebarOpen ? 'open' : ''}`}>
        <div className="logo-circle">
          {/* Grey Circle Logo placeholder from Image 2 */}
          <div className="restaurant-logo-placeholder" /> 
        </div>

        <div className="sidebar-list">
          {/* ICON 1 (Active/Dashboard) */}
          <button
            className={`sidebar-btn ${active === 'analytics' ? 'active' : ''}`}
            onClick={() => setActiveAndClose('analytics')}
            aria-label="Analytics"
          >
            <span className="inner-square" />
            {/* Icon 1 - Matches Image 2 */}
            <svg viewBox="0 0 24 24" width="20" height="20" aria-hidden><rect x="4" y="4" width="6" height="6" rx="1" fill="#0F172A" /><rect x="14" y="4" width="6" height="6" rx="1" fill="#0F172A" /><rect x="4" y="14" width="6" height="6" rx="1" fill="#0F172A" /><rect x="14" y="14" width="6" height="6" rx="1" fill="#0F172A" /></svg>
          </button>

          {/* ICON 2 (Tables/Receipt) */}
          <button
            className={`sidebar-btn ${active === 'tables' ? 'active' : ''}`}
            onClick={() => setActiveAndClose('tables')}
            aria-label="Tables"
          >
            <span className="inner-square" />
            {/* Icon 2 - Matches Image 2 */}
            <svg viewBox="0 0 24 24" width="20" height="20" aria-hidden><path d="M17 2H7C5.89543 2 5 2.89543 5 4V20C5 21.1046 5.89543 22 7 22H17C18.1046 22 19 21.1046 19 20V4C19 2.89543 18.1046 2 17 2Z" stroke="#0F172A" strokeWidth="1.4" strokeLinecap="round" strokeLinejoin="round"/><path d="M15 6H9" stroke="#0F172A" strokeWidth="1.4" strokeLinecap="round"/><path d="M15 10H9" stroke="#0F172A" strokeWidth="1.4" strokeLinecap="round"/><path d="M11 14H9" stroke="#0F172A" strokeWidth="1.4" strokeLinecap="round"/></svg>
          </button>

          {/* ICON 3 (Kitchen/Clipboard) */}
          <button
            className={`sidebar-btn ${active === 'kitchen' ? 'active' : ''}`}
            onClick={() => setActiveAndClose('kitchen')}
            aria-label="Kitchen"
          >
            <span className="inner-square" />
            {/* Icon 3 - Matches Image 2 */}
            <svg viewBox="0 0 24 24" width="20" height="20" aria-hidden><path d="M16 4H8C6.89543 4 6 4.89543 6 6V20C6 21.1046 6.89543 22 8 22H16C17.1046 22 18 21.1046 18 20V6C18 4.89543 17.1046 4 16 4Z" stroke="#0F172A" strokeWidth="1.4" strokeLinecap="round" strokeLinejoin="round"/><path d="M10 2V6" stroke="#0F172A" strokeWidth="1.4" strokeLinecap="round"/><path d="M14 2V6" stroke="#0F172A" strokeWidth="1.4" strokeLinecap="round"/><path d="M10 10H14" stroke="#0F172A" strokeWidth="1.4" strokeLinecap="round"/></svg>
          </button>

          {/* ICON 4 (Products/Bar Chart) */}
          <button
            className={`sidebar-btn ${active === 'products' ? 'active' : ''}`}
            onClick={() => setActiveAndClose('products')}
            aria-label="Add Product"
          >
            <span className="inner-square" />
            {/* Icon 4 - Matches Image 2 */}
            <svg viewBox="0 0 24 24" width="20" height="20" aria-hidden><path d="M3 12H5V20H3V12Z" stroke="#0F172A" strokeWidth="1.4"/><path d="M11 4H13V20H11V4Z" stroke="#0F172A" strokeWidth="1.4"/><path d="M19 8H21V20H19V8Z" stroke="#0F172A" strokeWidth="1.4"/></svg>
          </button>
        </div>
      </aside>

      {/* MAIN */}
      <main className="main-area">
        <header className="header-row">
          <div className="header-left">
            <button
              className="hamburger"
              aria-label="Toggle sidebar"
              onClick={() => setSidebarOpen((s) => !s)}
            >
              <svg width="20" height="14" viewBox="0 0 20 14" fill="none" aria-hidden><rect width="20" height="2" rx="1" fill="#0F172A" /><rect y="6" width="20" height="2" rx="1" fill="#0F172A" /><rect y="12" width="20" height="2" rx="1" fill="#0F172A" /></svg>
            </button>
          </div>

          <div className="header-right">
            <input
              className="filter-input"
              placeholder="Filter..." 
              value={filter}
              onChange={(e) => setFilter(e.target.value)}
            />
            <button className="action" onClick={() => setAppliedFilter(filter)}>
              Filter
            </button>
             <button className="action" onClick={() => {setFilter(''); setAppliedFilter('');}}>
              Clear
            </button>

            <div className="header-actions">
              <button className="action primary" disabled>
                Admin Dashboard
              </button>
              {/* This button now navigates to the User App */}
              <button className="action" onClick={() => navigate('/')}>
                Mobile Customer
              </button>
            </div>
          </div>
        </header>

        <section className="page-shell" style={{ filter: checkFilter('Page') ? 'none' : filterBlur }}>
          {/* Title changes based on active section */}
          {active === 'analytics' && <h2 className="page-title">Analytics</h2>}
          {active === 'tables' && <h2 className="page-title">Table Management</h2>}
          {active === 'kitchen' && <h2 className="page-title">Kitchen Order Line</h2>}
          {active === 'products' && <h2 className="page-title">Add New Product</h2>}

          {active === 'analytics' && (
            <Analytics 
              orders={orders} 
              tables={tables} 
              chefs={chefs} // Pass chefs state
              filterText={appliedFilter}
              checkFilter={checkFilter}
              filterBlur={filterBlur}
            />
          )}

          {active === 'tables' && (
            <Tables 
              tables={tables || []}
              orders={orders || []} 
              deleteTable={deleteTable} 
              addTable={addTable}
              checkFilter={checkFilter}
              filterBlur={filterBlur}
            />
          )}

          {active === 'kitchen' && (
            <Kitchen 
              orders={orders || []} 
              updateOrderStatus={updateOrderStatus}
              checkFilter={checkFilter}
              filterBlur={filterBlur} 
            />
          )}

          {active === 'products' && <AddProduct addProduct={addProduct} />}
          
        </section>
      </main>
    </div>
  );
}
